/* Original training cases. Complexity labels and pace targets are editorial, not Bryq norms. */
'use strict';
const EXPERT_QUESTIONS=[];
function expertPassage(key,sentences,items){
  items.forEach(([statement,answer,explanation,trap,evidence,why,worlds],i)=>EXPERT_QUESTIONS.push({
    id:`expert-v-${key}-${i}`,family:`expert-v-${key}`,d:'reason',kind:'verbal',lv:5,
    fr:`Selon ce passage uniquement : ${statement}`,o:['Vrai','Faux','Impossible à déterminer'],a:answer,
    x:explanation,stimulus:sentences.join(' '),sentences,trap,evidence,why,worlds:worlds||null,
    rule:TRAPS[trap],hint:'Repère le groupe concerné, le moment et la direction de la règle. Cherche une preuve ou deux situations compatibles.',targetSeconds:70
  }));
}
