for(const [id,fr,rows,a,why] of DETAIL_CASES){
 const o=rows.map((_,i)=>`Ligne ${String.fromCharCode(65+i)}`);
 const table=`<div class="table-scroll"><table><caption>Tableau à vérifier</caption><thead><tr><th>Ligne</th><th>Champ 1</th><th>Champ 2</th><th>Champ 3</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><th>${String.fromCharCode(65+i)}</th>${r.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
 expertCase(`d-${id}`,'reason',fr,o,a,why[a],why,{kind:'detail',trap:'detail',table,targetSeconds:45,detailRows:rows});
}

const SJT_CASES=[
 ['alerte','La direction attend ce soir une synthèse pour décider d’un décaissement. Deux sources officielles donnent des statuts différents pour une condition préalable. Le responsable de la donnée est joignable, et tu peux encore mettre à jour la synthèse. Quelle première réponse est la plus solide ?',
  ['Utiliser la source la plus récente et expliquer le choix dans une note à la direction.','Demander au responsable de rapprocher les preuves, signaler l’incertitude et actualiser la synthèse avant décision.','Reporter toute la synthèse jusqu’à réception d’une attestation signée par les deux services.','Retenir le statut le plus prudent et laisser au comité la responsabilité de le rectifier.'],1,
  ['La récence ne suffit pas à résoudre une contradiction sur une condition décisive.','La vérification reste possible ; rendre visible l’incertitude protège la décision sans bloquer inutilement le travail.','L’attestation des deux services n’est pas une exigence posée et peut empêcher une clarification disponible.','Un choix prudent mais non vérifié peut être faux et ne résout pas la divergence.']],
 ['plainte','Une coopérative signale que le partenaire d’exécution exclut certaines femmes de réunions essentielles. Le partenaire conteste les faits. Tu n’as pas encore vérifié la situation et une rencontre est prévue demain. Que fais-tu en priorité ?',
  ['Demander au partenaire de présenter demain son bilan de participation et discuter de ses conclusions.','Organiser demain une confrontation publique entre la coopérative et le partenaire pour clarifier les faits.','Recueillir les faits par un canal accessible et confidentiel, puis faire examiner l’alerte par le responsable compétent.','Suspendre immédiatement tout le programme et informer les bénéficiaires que l’exclusion est établie.'],2,
  ['Les seuls chiffres du partenaire ne suffisent pas à comprendre une exclusion contestée.','Une confrontation publique peut exposer les plaignantes et empêcher une expression libre.','L’écoute protégée et la vérification permettent une réponse proportionnée sans présumer du résultat.','Il faut traiter l’alerte sérieusement sans présenter comme établi ce qui reste à vérifier.']],
 ['cadeau','À la veille d’une sélection de prestataires, un candidat t’offre une invitation professionnelle dont la valeur n’est pas claire. Tu n’es pas seul décideur, mais tu contribues à l’analyse. Quelle démarche protège le mieux l’impartialité ?',
  ['Décliner l’avantage, en informer le canal compétent et vérifier les mesures nécessaires pour poursuivre l’analyse impartialement.','Accepter seulement si le candidat confirme par écrit que l’invitation est ouverte à tous les analystes.','Transférer l’invitation à un collègue qui ne vote pas, puis poursuivre normalement ton analyse.','Conserver l’invitation sans l’utiliser avant la fin de la sélection et la mentionner ensuite.'],0,
  ['La contribution à l’analyse suffit à justifier le traitement transparent d’un avantage offert.','L’ouverture à plusieurs analystes ne supprime pas le risque d’influence.','Le transfert maintient l’avantage et évite sa gestion officielle.','Reporter la déclaration laisse subsister un risque pendant la sélection.']],
 ['delegation','Une tâche urgente exige une validation que tu n’es pas habilité à donner. Le signataire habituel est absent, mais un délégataire formel est disponible. Une équipe propose ton accord provisoire pour éviter un retard. Que fais-tu ?',
  ['Donner ton accord provisoire et faire régulariser la signature par le délégataire plus tard.','Attendre le retour du signataire habituel pour préserver la cohérence de toutes les validations.','Demander à l’équipe de considérer le dossier comme validé à condition de ne pas encore l’envoyer.','Transmettre les éléments au délégataire habilité et organiser avec lui la validation dans le délai.'],3,
  ['La régularisation ultérieure ne crée pas ton habilitation.','Un délégataire formel est disponible : l’attente n’est pas nécessaire.','Une validation informelle reste une décision sans habilitation, même avant l’envoi.','Cette voie respecte la responsabilité de validation et permet de tenir le délai.']],
 ['equipe','Ton collègue livre une analyse incomplète avant une réunion importante. Il dit avoir suivi un cadrage différent, validé par un autre responsable. Il reste du temps pour corriger les points critiques, mais pas pour tout refaire. Quelle réponse est la plus utile ?',
  ['Présenter ton propre cadrage comme la référence et refaire les parties manquantes sans solliciter le collègue.','Recaler rapidement les attendus avec les responsables, répartir les corrections critiques et signaler les limites restantes.','Reporter la réunion et demander une nouvelle analyse intégrale conforme à ton cadrage.','Conserver l’analyse reçue et préciser à la réunion qu’elle reflète le cadrage de l’autre responsable.'],1,
  ['Cela peut reproduire une divergence de cadrage et écarter l’expertise utile du collègue.','La clarification, la priorisation et la transparence traitent le conflit d’attendus dans le temps disponible.','Le scénario permet encore les corrections essentielles ; une reprise totale est disproportionnée.','Attribuer la responsabilité ne rend pas l’analyse exploitable.']],
 ['terrain','Deux sites demandent une visite à la même date. Le premier présente une alerte de sécurité à vérifier ; le second attend une visite de routine déjà promise. Une équipe qualifiée peut couvrir le second si tu lui transmets le dossier. Que privilégies-tu ?',
  ['Maintenir la visite promise et demander au premier site un rapport détaillé pour la semaine suivante.','Annuler les deux visites et demander à la direction de choisir un site prioritaire.','Vérifier l’urgence, organiser une réponse qualifiée au premier site et coordonner la visite du second avec l’équipe disponible.','Visiter successivement les deux sites en réduisant chaque visite pour respecter les promesses.'],2,
  ['Une promesse de routine ne suffit pas à justifier le retard de traitement d’une alerte de sécurité.','Une alternative opérationnelle permet de couvrir les deux besoins.','La priorité au risque et la délégation coordonnée préservent les obligations utiles.','Réduire les visites sans examiner les besoins risque de compromettre leur qualité.']],
 ['chiffres','Une erreur de consolidation modifie un chiffre déjà transmis à un partenaire. Tu as identifié la source et la valeur correcte. Le partenaire doit utiliser le document dans une réunion prochaine. Quelle réponse est la plus appropriée ?',
  ['Faire corriger et transmettre une version clairement identifiée, expliquer l’effet de l’erreur et demander le remplacement du document.','Remplacer silencieusement le document partagé afin que le partenaire utilise désormais la bonne version.','Attendre la revue mensuelle, puis inclure le chiffre correct avec les autres mises à jour.','Envoyer le chiffre corrigé au partenaire et conserver le document pour garder la trace de la première version.'],0,
  ['La correction doit être traçable et exploitable avant la réunion.','La correction silencieuse ne garantit pas que le partenaire remplace sa copie.','Attendre expose la réunion à une information erronée connue.','Le maintien sans identification claire des deux versions entretient une incohérence.']],
 ['confidentialite','Un partenaire habilité à recevoir une synthèse te demande la liste nominative complète pour une analyse urgente. Ton mandat de partage ne couvre que les statistiques anonymes. Une extension d’accès peut être examinée par le responsable des données. Que fais-tu ?',
  ['Transmettre la liste sous mot de passe et demander au partenaire de limiter son usage à cette analyse.','Transmettre uniquement les noms, car les données sensibles sont dans les autres colonnes du registre.','Refuser toute collaboration avec le partenaire jusqu’à la prochaine revue complète de son habilitation.','Fournir la synthèse autorisée et faire examiner la demande nominative selon sa finalité et les droits d’accès.'],3,
  ['Un mot de passe ne remplace pas l’autorisation de partage.','Les noms restent des données nominatives au-delà du mandat donné.','La synthèse autorisée permet de poursuivre la collaboration.','Cette réponse satisfait le besoin permis tout en traitant l’extension de manière contrôlée.']],
 ['pression','Une autorité locale demande d’ajouter un site à une liste approuvée. Le besoin semble réel, mais les critères et la capacité budgétaire n’ont pas été examinés pour ce site. La procédure autorise les demandes complémentaires. Quelle réponse est la plus constructive ?',
  ['Ajouter le site sous réserve de confirmation budgétaire et expliquer au comité la nécessité locale.','Enregistrer la demande, la soumettre aux mêmes critères et préciser qu’aucun ajout n’est acquis avant décision.','Exclure définitivement le site pour éviter que la pression locale influence le programme.','Demander au site de mobiliser sa contribution avant d’examiner les autres critères d’admissibilité.'],1,
  ['Une réserve financière ne remplace pas l’examen et la décision requis.','Le besoin peut être examiné sans contourner l’équité ni promettre une sélection.','La pression ne justifie pas à elle seule un rejet définitif d’un besoin recevable.','Une contribution anticipée peut créer une attente sans examen des critères.']],
 ['innovation','Un outil nouveau réduit le temps de saisie dans un pilote. L’équipe veut l’imposer sur tous les sites, mais certains ont une faible connexion et aucune mesure de qualité des données n’a été faite. Quelle suite est la plus solide ?',
  ['Étendre immédiatement l’outil et corriger les problèmes de connexion à mesure qu’ils apparaissent.','Conserver définitivement l’ancien outil pour éviter les risques d’une nouvelle méthode.','Tester qualité et faisabilité sur des sites variés, prévoir une solution hors ligne et décider de l’extension sur ces résultats.','Étendre uniquement aux sites connectés et considérer leur résultat comme représentatif de tous les sites.'],2,
  ['Le gain de temps ne prouve ni la qualité ni l’utilisabilité universelle.','Une innovation utile mérite une validation ciblée, pas un rejet définitif.','La vérification élargie répond aux deux incertitudes et garde la possibilité d’innover.','Une sélection des sites les mieux connectés limite la généralisation.']],
 ['retour','Un responsable formule devant l’équipe une critique que tu estimes inexacte. Le désaccord concerne une méthode et la réunion porte sur une décision urgente. Quelle réaction préserve le mieux la qualité du travail ?',
  ['Clarifier brièvement le point factuel utile à la décision, puis convenir d’un échange séparé sur la méthode avec les pièces disponibles.','Répondre point par point à toute la critique pendant la réunion pour corriger immédiatement l’image de ton travail.','Accepter la critique sans clarification et modifier ensuite l’analyse pour satisfaire le responsable.','Demander à l’équipe de choisir laquelle des deux méthodes lui semble la plus crédible.'],0,
  ['La correction factuelle utile protège la décision ; l’échange séparé permet un examen complet sans accaparer la réunion.','Une défense exhaustive peut faire perdre l’objectif urgent.','L’acceptation sans examen peut dégrader la qualité de l’analyse.','Un vote d’opinion ne remplace pas la comparaison des méthodes et des preuves.']],
 ['risque','Un fournisseur propose de remplacer une pièce indisponible par un composant présenté comme équivalent. Le calendrier est tendu et tu n’as pas la compétence technique pour confirmer l’équivalence. Un spécialiste du projet est disponible. Que fais-tu ?',
  ['Accepter si le fournisseur garantit par écrit qu’il remplacera la pièce en cas de problème.','Refuser toute substitution jusqu’à la disponibilité de la pièce prévue initialement.','Demander aux usagers si le composant leur semble acceptable et valider sur leur accord.','Faire vérifier l’équivalence et ses impacts par le spécialiste, puis suivre la validation applicable avant substitution.'],3,
  ['La garantie du fournisseur ne remplace pas la vérification technique et la validation.','Une substitution acceptable peut éviter le retard après examen compétent.','Les usagers apportent un avis utile, mais pas la validation technique manquante.','Cette réponse traite le risque sans inventer une compétence ni bloquer une solution possible.']]
];
for(const [id,fr,o,a,why] of SJT_CASES)expertCase(`s-${id}`,'sjt',fr,o,a,why[a],why,{source:'yppskills',targetSeconds:65});

SOURCES.guarantees={title:'BAD — garanties et mobilisation des capitaux',url:'https://www.afdb.org/en/projects-and-operations/financial-products/african-development-bank/guarantees',date:'Consulté le 1er octobre 2026'};
SOURCES.additionality={title:'BAD — opérations non souveraines et additionnalité',url:'https://www.afdb.org/en/private-sector/how-work-us',date:'Consulté le 1er octobre 2026'};
SOURCES.safeguards={title:'BAD — Système de sauvegardes intégré actualisé',url:'https://www.afdb.org/en/news-and-events/press-releases/african-development-bank-groups-updated-integrated-safeguards-system-iss-becomes-effective-71539',date:'Consulté le 1er octobre 2026'};
const BANK_CASES=[
 ['addition','Une opération privée rentable dispose déjà de financement commercial aux mêmes conditions que l’appui proposé par la BAD. Aucun apport technique ou effet catalytique supplémentaire n’est identifié. Quelle question manque avant de justifier l’intervention ?',
  ['Quel avantage financier ou non financier la participation apporte-t-elle au-delà de ce que le marché fournirait seul ?','Le promoteur peut-il accroître sa marge en remplaçant le financement commercial par les ressources proposées ?','Le projet appartient-il à un secteur prioritaire, même si les conditions disponibles restent identiques ?','Le projet possède-t-il déjà une capacité de remboursement suffisante pour les prêteurs commerciaux ?'],0,
  ['L’additionnalité examine la valeur supplémentaire de l’intervention.','Une meilleure marge privée ne démontre pas une contribution additionnelle au développement.','L’alignement sectoriel est utile mais ne répond pas à l’absence d’additionnalité.','La viabilité est posée ; elle ne suffit pas à justifier l’apport de la Banque.'],'additionality'],
 ['garantie','Des prêteurs envisagent un projet viable mais craignent la non-exécution d’une obligation contractuelle de l’autorité publique. Le promoteur demande de couvrir aussi tout risque commercial. Quel cadrage répond au risque identifié ?',
  ['Accorder une subvention couvrant les revenus commerciaux futurs pour supprimer toute incertitude de recettes.','Étudier une couverture ciblée de l’obligation publique, en précisant exclusions, responsabilités et risques restant aux parties.','Garantir tous les risques de l’opération pour éviter que les prêteurs demandent une analyse complémentaire.','Financer exclusivement les équipements et considérer l’exécution de l’obligation publique comme un sujet séparé.'],1,
  ['La subvention de revenus ne cible pas le défaut d’obligation publique.','Les garanties de risque peuvent cibler l’exécution d’obligations publiques ; leur couverture n’est pas automatiquement universelle.','Une garantie ciblée ne supprime ni les limites contractuelles ni l’analyse des risques commerciaux.','Les équipements ne résolvent pas le risque posé.'],'guarantees'],
 ['integration','Deux pays disposent d’une liaison routière, mais les camions restent bloqués par des procédures incompatibles et des contrôles successifs. Quelle composante complète le mieux l’investissement physique dans l’objectif « Intégrer l’Afrique » ?',
  ['Ajouter un nouveau tronçon parallèle pour augmenter la capacité physique disponible aux frontières.','Subventionner temporairement le carburant des transporteurs opérant sur le corridor existant.','Coordonner les procédures et les organismes frontaliers pour rendre la liaison effectivement utilisable.','Mesurer uniquement les kilomètres réalisés afin de comparer les deux investissements nationaux.'],2,
  ['Le goulot décrit est procédural.','La subvention réduit un coût mais ne traite pas les incompatibilités.','L’intégration combine la connexion physique et les conditions de circulation effective.','Un indicateur de réalisation ne traite pas le blocage.'],'regional2026'],
 ['high5','Un programme associe irrigation, transformation locale et accès aux marchés régionaux. Quel raisonnement évite de réduire son intérêt stratégique à une seule étiquette High 5 ?',
  ['Retenir uniquement l’irrigation car le premier investissement détermine toutes les priorités du programme.','Retenir uniquement l’industrialisation car la transformation annule les objectifs de production agricole.','Attribuer automatiquement les cinq priorités sans expliquer les mécanismes de contribution.','Relier les composantes à leurs résultats attendus en agriculture, valeur ajoutée et intégration régionale.'],3,
  ['L’ordre des investissements ne résume pas leurs contributions.','Une composante de transformation ne supprime pas le lien à l’agriculture.','Une liste sans mécanisme n’établit pas la contribution.','Un projet peut servir plusieurs priorités avec des liens explicites.'],'strategy'],
 ['concession','Un pays admissible a de faibles capacités de financement et un important besoin de développement. On examine le guichet concessionnel du Groupe BAD. Quelle distinction institutionnelle est correcte ?',
  ['Le FAD est le guichet concessionnel du Groupe ; son appui ne dispense pas d’examiner la viabilité et les résultats.','Le FAD est le guichet commercial réservé aux sociétés privées capables d’emprunter sans garantie souveraine.','Le FAD remplace les autorités nationales pour toutes les décisions de politique budgétaire des pays soutenus.','Le FAD finance chaque opération admissible automatiquement, sans analyse de la capacité d’exécution.'],0,
  ['La concessionnalité décrit les conditions du guichet et non une absence d’examen.','Cette description ne correspond pas au guichet concessionnel.','Un appui de développement ne transfère pas toutes les décisions souveraines.','L’admissibilité du pays ne rend pas chaque opération automatique.'],'adf'],
 ['emploi','Un projet de formation annonce un nombre élevé de participants. Dans la logique d’amélioration de la qualité de vie, quelle vérification relie le mieux cette réalisation à l’objectif d’emploi ?',
  ['Comparer le nombre de salles ouvertes entre les centres de formation partenaires.','Examiner l’insertion et la qualité des emplois, en tenant compte des profils et des obstacles rencontrés.','Comparer uniquement le nombre de certificats imprimés aux prévisions de l’équipe.','Additionner les heures de formation pour établir directement le nombre d’emplois créés.'],1,
  ['Les salles renseignent sur les moyens, pas l’emploi.','L’insertion et la qualité des emplois sont plus proches du résultat recherché.','Un certificat n’établit pas une insertion.','Des heures ne se convertissent pas automatiquement en emplois.'],'strategy'],
 ['energie','Un projet d’électrification a livré des branchements, mais des coupures et des coûts élevés empêchent les entreprises locales d’utiliser le service. Quel suivi répond le mieux à l’objectif de développement ?',
  ['Le nombre de branchements réalisés, utilisé comme indicateur suffisant de transformation économique.','Le volume total investi, utilisé comme preuve d’amélioration des activités productives.','L’accès effectif, la fiabilité, l’abordabilité et les usages productifs, en plus des branchements.','La capacité nominale installée, sans information sur le service reçu par les entreprises.'],2,
  ['Une connexion matérielle ne suffit pas à démontrer un usage utile.','Une dépense ne démontre pas le service ni ses effets.','Le suivi doit examiner si l’accès permet effectivement les usages attendus.','La capacité nominale ne mesure pas le service fourni.'],'mission'],
 ['sauvegardes','Une opération de transport peut améliorer l’accès au marché, mais risque aussi d’affecter des terres et des moyens de subsistance. Quelle lecture des sauvegardes environnementales et sociales est correcte ?',
  ['L’intérêt économique rend inutile l’analyse des impacts négatifs avant l’exécution.','Les sauvegardes s’appliquent uniquement si l’opération est entièrement financée par le secteur public.','Les sauvegardes consistent uniquement à vérifier que le chantier respecte son budget.','L’analyse et la gestion des impacts accompagnent l’opération, avec prise en compte des personnes affectées.'],3,
  ['Un bénéfice économique ne supprime pas les impacts à examiner.','Les risques ne disparaissent pas du fait de la modalité de financement.','L’exécution financière ne remplace pas les exigences environnementales et sociales.','Les sauvegardes relient le développement à la prévention et à la gestion des impacts.'],'safeguards'],
 ['finance','Une garantie publique attire des capitaux privés sur une opération. Quelle information est nécessaire pour apprécier son effet catalytique sans confondre financement total et financement mobilisé ?',
  ['La participation privée additionnelle attribuable au mécanisme, les risques assumés et les conditions de l’opération.','Le montant total du projet, considéré comme entièrement mobilisé par la garantie proposée.','Le nombre de partenaires présents à la cérémonie de signature du dispositif.','Le seul montant nominal de la garantie, supposé égal au capital privé engagé.'],0,
  ['L’effet catalytique demande de distinguer la participation additionnelle et les risques transférés.','Le financement total inclut des ressources qui peuvent ne pas être causées par le mécanisme.','Une participation à une cérémonie n’est pas un engagement financier.','Garantie et capitaux engagés ne sont pas des montants automatiquement identiques.'],'additionality'],
 ['strategie','L’équipe doit relier un projet à la Stratégie décennale 2024–2033. Le projet accroît la production, mais les groupes vulnérables risquent d’être exclus et les équipements sont exposés aux inondations. Quelle analyse est la plus complète ?',
  ['Conclure à l’alignement dès que le volume de production augmente.','Examiner les résultats de croissance avec l’inclusion, la résilience et les modalités de mise en œuvre.','Remplacer le suivi économique par une description exclusivement environnementale.','Reporter toute analyse de vulnérabilité après la fin du financement.'],1,
  ['Une croissance isolée ne répond pas aux risques d’exclusion et de fragilité.','L’alignement doit examiner les résultats et les dimensions transversales de la stratégie.','Les dimensions économiques restent pertinentes.','Les risques doivent informer la conception et l’exécution.'],'strategy'],
 ['cycle','Une annonce officielle confirme l’approbation d’une opération. Un candidat écrit que les bénéficiaires ont déjà reçu l’ensemble des résultats promis. Quelle correction est la plus précise ?',
  ['Remplacer « approuvé » par « annoncé » et conserver l’ensemble des résultats comme atteints.','Affirmer que l’opération a échoué puisqu’aucun résultat n’est décrit dans l’annonce.','Distinguer l’approbation des décaissements, de l’exécution et des résultats effectivement observés.','Supprimer toutes les informations sur l’opération car une approbation ne vaut aucune information.'],2,
  ['Changer le verbe ne vérifie pas les résultats.','Le manque de résultat décrit ne prouve pas un échec.','Les étapes sont distinctes et nécessitent des preuves différentes.','L’approbation est un fait utile, sans prouver tout le reste.'],'news'],
 ['nonso','Une entreprise publique sollicite un financement sans garantie gouvernementale. Quel point évite une classification automatique de l’opération à partir de la seule propriété de l’entreprise ?',
  ['Toute entreprise publique implique forcément une garantie souveraine, même non prévue au contrat.','L’absence de garantie élimine toute analyse de l’éligibilité et des risques de l’entreprise.','Une opération privée exige toujours que l’État ne possède aucune part dans l’entreprise.','Examiner l’éligibilité de l’entité et la structure de financement, notamment l’absence de garantie souveraine.'],3,
  ['La propriété publique ne crée pas automatiquement la garantie.','L’absence de garantie ne dispense pas de l’examen.','Certaines entités publiques admissibles peuvent accéder aux opérations non souveraines.','La structure de l’opération et l’éligibilité doivent être examinées.'],'additionality']
];
for(const [id,fr,o,a,why,source] of BANK_CASES)expertCase(`b-${id}`,'afdb',fr,o,a,why[a],why,{source});

const DEVELOPMENT_CASES=[
 ['climat','Une zone agricole connaît une forte variabilité des pluies. Un système d’irrigation dépend lui-même d’une ressource en eau fragile. Quelle décision renforce la résilience sans déplacer le risque ?',
  ['Évaluer la disponibilité durable de l’eau, les usages concurrents et la maintenance avant de fixer la solution.','Dimensionner l’ouvrage seulement sur la surface à irriguer afin de maximiser la production potentielle.','Garantir les mêmes volumes d’eau chaque saison sans tenir compte des conditions hydrologiques.','Retenir une technologie identique sur tous les sites pour simplifier les futurs contrats.'],0,
  ['La résilience exige d’examiner la dépendance et les contraintes de la ressource.','La surface ne suffit pas à établir la ressource disponible.','Une promesse ne crée pas une ressource durable.','La standardisation ne répond pas aux différences hydrologiques.']],
 ['dette','Un État finance un équipement de long terme par une dette à refinancer rapidement. Les recettes du projet arrivent tard et restent incertaines. Quel risque est le plus directement décrit ?',
  ['Un risque de confusion entre production agricole et activité industrielle.','Un risque de refinancement et de décalage entre échéances de dette et flux disponibles.','Un risque nécessairement éliminé dès que le projet est économiquement utile.','Un risque exclusivement lié à la présence d’un prêteur étranger.'],1,
  ['Le secteur n’est pas le décalage posé.','L’échéance peut arriver avant les ressources nécessaires au remboursement.','L’utilité n’assure pas la disponibilité des flux à chaque échéance.','Un tel décalage peut exister aussi avec un prêteur domestique.']],
 ['genre','Un programme de crédit augmente les prêts à des entreprises dirigées par des femmes, mais certaines bénéficiaires ne contrôlent pas l’utilisation des fonds. Quelle mesure complète le mieux le suivi de volume ?',
  ['Le nombre total de dossiers instruits par l’établissement prêteur.','Le volume global des prêts accordés à tous les emprunteurs de la zone.','Le contrôle effectif des ressources, leur usage productif et les résultats pour les bénéficiaires.','Le seul nombre de signatures présentes sur les contrats de prêt.'],2,
  ['L’instruction est un processus, pas le contrôle des ressources.','Un agrégat global peut masquer la situation des bénéficiaires.','L’inclusion exige de regarder l’accès effectif et le pouvoir d’usage.','Une signature ne démontre pas le contrôle effectif.']],
 ['commerce','Un pays produit davantage de denrées exportables, mais les rejets à la frontière augmentent pour non-conformité. Quelle intervention traite le plus directement ce problème ?',
  ['Financer l’extension de la surface cultivée pour compenser les volumes rejetés.','Réduire le coût de stockage sans examiner les motifs de non-conformité.','Augmenter les subventions aux exportateurs selon leur volume déclaré.','Renforcer qualité, traçabilité et respect des exigences applicables aux marchés visés.'],3,
  ['Produire plus ne corrige pas la non-conformité.','Le stockage peut contribuer à la qualité, mais il faut traiter les motifs établis.','Une subvention de volume peut laisser le problème intact.','Cette intervention répond à la cause des rejets.']],
 ['emploi','Une subvention vise l’emploi durable des jeunes. Des placements sont annoncés, mais les départs sont fréquents après la fin de la subvention. Quelle question vérifie la durabilité ?',
  ['Quelle est la rétention après l’appui, avec quels revenus, conditions et perspectives d’activité ?','Combien de logos des entreprises partenaires figurent sur les supports du programme ?','Combien de jeunes ont reçu un message confirmant leur inscription au dispositif ?','Combien d’heures les équipes ont consacré aux réunions de placement ?'],0,
  ['La rétention et la qualité de l’activité décrivent la durabilité recherchée.','La visibilité des partenaires ne prouve pas l’emploi durable.','L’inscription ne garantit pas une activité conservée.','Le temps de gestion ne mesure pas la persistance de l’emploi.']],
 ['fragilite','Un ouvrage d’eau bénéficie à plusieurs communautés dont les droits d’accès sont contestés. La solution technique est validée, mais les règles de partage ne le sont pas. Quel risque reste décisif ?',
  ['Le seul risque que l’ouvrage soit plus grand que les autres ouvrages de la région.','Un risque de conflit et d’exclusion si les règles d’accès et les responsabilités restent contestées.','Un risque nécessairement nul puisque la technologie a été validée.','Un risque limité au coût d’achat initial des équipements.'],1,
  ['La taille comparative n’est pas le risque posé.','L’usage durable dépend aussi d’accords légitimes sur l’accès.','La validation technique ne résout pas les tensions sociales.','Les règles contestées dépassent le coût initial.']],
 ['mobilisation','Un pays veut accroître ses ressources domestiques en améliorant le recouvrement fiscal. Les entreprises soulignent la complexité et l’incertitude des procédures. Quelle combinaison répond au besoin sans ignorer cette contrainte ?',
  ['Augmenter les prélèvements sans modifier les procédures ni la qualité du service.','Remplacer durablement les recettes domestiques par des emprunts à court terme.','Améliorer l’assiette, la prévisibilité, le service et la conformité tout en examinant les effets sur l’activité.','Exiger que les entreprises financent elles-mêmes l’ensemble de la réforme administrative.'],2,
  ['Un taux plus élevé ne corrige pas la complexité du système.','Le refinancement court ne remplace pas durablement la mobilisation domestique.','La collecte et un environnement prévisible peuvent être améliorés ensemble.','Cela ne décrit pas une réforme opérationnelle du système fiscal.']],
 ['numerique','Une application de conseil atteint beaucoup de téléchargements, mais les utilisateurs ruraux disposent de peu de connexion et ne l’utilisent presque plus. Quel changement répond au diagnostic ?',
  ['Augmenter uniquement le budget publicitaire pour obtenir davantage de téléchargements.','Mesurer uniquement le nombre de fonctionnalités ajoutées par les développeurs.','Réserver toutes les fonctionnalités aux téléphones les plus récents disponibles.','Adapter l’accès hors ligne ou à faible débit et vérifier les usages et décisions réellement améliorés.'],3,
  ['La publicité ne résout pas l’obstacle d’usage.','Le volume de fonctionnalités ne prouve pas leur utilité.','La restriction peut aggraver l’exclusion.','L’adaptation et le suivi des usages répondent au besoin observé.']],
 ['assurance','Une assurance agricole déclenche le paiement à partir d’un indice climatique régional. Un producteur subit une perte importante, mais l’indice ne déclenche pas. Quel problème illustre ce scénario ?',
  ['Un risque de base entre le déclencheur indiciel et la perte réellement subie.','Une preuve que toute assurance climatique rembourse forcément chaque perte individuelle.','Un risque de remboursement du prêt qui disparaît dès la signature de l’assurance.','Une preuve que l’indice est toujours identique au rendement de chaque exploitation.'],0,
  ['L’indice peut ne pas refléter exactement la situation individuelle.','Le scénario décrit précisément l’absence de déclenchement.','L’assurance ne supprime pas automatiquement tout risque de crédit.','Un indice régional peut diverger du rendement individuel.']],
 ['logistique','Un centre de stockage moderne reste peu utilisé. Les producteurs vendent tôt pour couvrir des besoins de liquidité et les frais de dépôt sont mal compris. Quelle analyse est prioritaire ?',
  ['Conclure que les producteurs refusent la modernisation, sans examiner leurs contraintes.','Étudier les incitations, les besoins de liquidité et les conditions d’accès au stockage avant d’étendre l’équipement.','Construire davantage de centres identiques afin de créer une demande par la capacité disponible.','Mesurer seulement la capacité construite pour démontrer la réduction des pertes.'],1,
  ['Une faible utilisation peut être rationnelle face aux contraintes.','L’ouvrage doit répondre aux conditions économiques et pratiques d’utilisation.','La capacité supplémentaire peut rester inutilisée pour les mêmes raisons.','La capacité ne démontre pas les pertes évitées.']],
 ['impact','Un programme constate une hausse du revenu des participants pendant une hausse générale des prix agricoles. Quelle conclusion est la plus rigoureuse ?',
  ['La hausse observée mesure exactement l’effet du programme sur le revenu.','La hausse générale prouve que le programme n’a eu aucun effet.','La variation est observée, mais l’effet propre demande une comparaison crédible et un examen des autres influences.','Le nombre de participants suffit à isoler l’effet du changement de prix.'],2,
  ['Le contexte peut avoir contribué au changement.','Une influence externe possible n’exclut pas une contribution du programme.','Observation et attribution doivent être distinguées.','Un effectif ne crée pas un contrefactuel crédible.']],
 ['valeur','Une filière exporte une matière brute malgré une demande locale de transformation. L’électricité est irrégulière et les unités n’ont pas de débouchés contractualisés. Quel programme traite le mieux les contraintes conjointes ?',
  ['Subventionner seulement l’achat des machines pour faire apparaître une activité industrielle.','Augmenter seulement le volume brut exporté pour compenser l’absence de transformation.','Imposer une transformation locale immédiate sans modifier les conditions de production.','Combiner énergie fiable, capacités de transformation et accès commercial vérifié dans une séquence viable.'],3,
  ['La machine ne suffit pas sans énergie et clients.','L’exportation brute ne traite pas la demande de valorisation locale.','L’obligation ne rend pas les unités viables.','Les goulots sont complémentaires et doivent être traités ensemble.']]
];
for(const [id,fr,o,a,why] of DEVELOPMENT_CASES)expertCase(`a-${id}`,'africa',fr,o,a,why[a],why);
QUESTIONS.push(...EXPERT_QUESTIONS);
